registerPy("_collections", () => "\"\"\"Implementaci\u00f3n en Python de deque y defaultdict (los tipos en C de CPython).\"\"\"\nfrom reprlib import recursive_repr as _recursive_repr\nfrom operator import eq as _eq\nclass deque:\n    \"\"\"deque([iterable[, maxlen]]) --> deque object\n\n    A list-like sequence optimized for data accesses near its endpoints.\"\"\"\n    def __init__(self, iterable=(), maxlen=None):\n        if maxlen is not None:\n            if not isinstance(maxlen, int):\n                raise TypeError(\"an integer is required\")\n            if maxlen < 0:\n                raise ValueError(\"maxlen must be non-negative\")\n        self._d = []\n        self._maxlen = maxlen\n        self.extend(iterable)\n    @property\n    def maxlen(self):\n        return self._maxlen\n    def _trim_left(self):\n        if self._maxlen is not None and len(self._d) > self._maxlen:\n            del self._d[:len(self._d) - self._maxlen]\n    def _trim_right(self):\n        if self._maxlen is not None and len(self._d) > self._maxlen:\n            del self._d[self._maxlen:]\n    def append(self, x):\n        if self._maxlen == 0:\n            return\n        self._d.append(x)\n        self._trim_left()\n    def appendleft(self, x):\n        if self._maxlen == 0:\n            return\n        self._d.insert(0, x)\n        self._trim_right()\n    def extend(self, iterable):\n        if iterable is self:\n            iterable = list(iterable)\n        for x in iterable:\n            self.append(x)\n    def extendleft(self, iterable):\n        if iterable is self:\n            iterable = list(iterable)\n        for x in iterable:\n            self.appendleft(x)\n    def pop(self):\n        if not self._d:\n            raise IndexError(\"pop from an empty deque\")\n        return self._d.pop()\n    def popleft(self):\n        if not self._d:\n            raise IndexError(\"pop from an empty deque\")\n        return self._d.pop(0)\n    def clear(self):\n        self._d.clear()\n    def copy(self):\n        return self.__class__(self._d, self._maxlen)\n    __copy__ = copy\n    def count(self, x):\n        n = 0\n        for y in list(self._d):\n            if y is x or y == x:\n                n += 1\n        return n\n    def index(self, x, start=0, stop=None):\n        n = len(self._d)\n        if start < 0:\n            start = max(0, start + n)\n        if stop is None:\n            stop = n\n        elif stop < 0:\n            stop = max(0, stop + n)\n        for i in range(start, min(stop, n)):\n            y = self._d[i]\n            if y is x or y == x:\n                return i\n        raise ValueError(f\"{x!r} is not in deque\")\n    def insert(self, i, x):\n        if self._maxlen is not None and len(self._d) >= self._maxlen:\n            raise IndexError(\"deque already at its maximum size\")\n        self._d.insert(i, x)\n    def remove(self, value):\n        for i, y in enumerate(self._d):\n            if y is value or y == value:\n                del self._d[i]\n                return\n        raise ValueError(\"deque.remove(x): x not in deque\")\n    def reverse(self):\n        self._d.reverse()\n    def rotate(self, n=1):\n        d = self._d\n        if not d:\n            return\n        n %= len(d)\n        if n:\n            self._d = d[-n:] + d[:-n]\n    def __len__(self):\n        return len(self._d)\n    def __bool__(self):\n        return bool(self._d)\n    def __iter__(self):\n        return iter(list(self._d))\n    def __reversed__(self):\n        return reversed(list(self._d))\n    def __contains__(self, x):\n        for y in list(self._d):\n            if y is x or y == x:\n                return True\n        return False\n    def __getitem__(self, i):\n        if isinstance(i, slice):\n            raise TypeError(\"sequence index must be integer, not 'slice'\")\n        try:\n            return self._d[i]\n        except IndexError:\n            raise IndexError(\"deque index out of range\") from None\n    def __setitem__(self, i, x):\n        try:\n            self._d[i] = x\n        except IndexError:\n            raise IndexError(\"deque index out of range\") from None\n    def __delitem__(self, i):\n        try:\n            del self._d[i]\n        except IndexError:\n            raise IndexError(\"deque index out of range\") from None\n    def __add__(self, other):\n        if not isinstance(other, deque):\n            raise TypeError(f'can only concatenate deque (not \"{type(other).__name__}\") to deque')\n        r = self.copy()\n        r.extend(other)\n        return r\n    def __iadd__(self, other):\n        self.extend(other)\n        return self\n    def __mul__(self, n):\n        r = self.__class__(maxlen=self._maxlen)\n        r.extend(self._d * n)\n        return r\n    __rmul__ = __mul__\n    def __imul__(self, n):\n        items = self._d * n\n        self._d = []\n        self.extend(items)\n        return self\n    def __eq__(self, other):\n        if not isinstance(other, deque):\n            return NotImplemented\n        return self._d == other._d\n    def __lt__(self, other):\n        if not isinstance(other, deque):\n            return NotImplemented\n        return self._d < other._d\n    def __le__(self, other):\n        if not isinstance(other, deque):\n            return NotImplemented\n        return self._d <= other._d\n    def __gt__(self, other):\n        if not isinstance(other, deque):\n            return NotImplemented\n        return self._d > other._d\n    def __ge__(self, other):\n        if not isinstance(other, deque):\n            return NotImplemented\n        return self._d >= other._d\n    __hash__ = None\n    @_recursive_repr('[...]')\n    def __repr__(self):\n        if self._maxlen is None:\n            return f\"{type(self).__name__}({list(self._d)!r})\"\n        return f\"{type(self).__name__}({list(self._d)!r}, maxlen={self._maxlen})\"\n    def __reduce__(self):\n        return type(self), (list(self._d), self._maxlen)\n    def __sizeof__(self):\n        return 624 + 8 * len(self._d)\n    def __class_getitem__(cls, item):\n        from types import GenericAlias\n        return GenericAlias(cls, item)\nclass defaultdict(dict):\n    \"\"\"defaultdict(default_factory=None, /, [...]) --> dict with default factory\"\"\"\n    def __init__(self, default_factory=None, /, *args, **kwargs):\n        if default_factory is not None and not callable(default_factory):\n            raise TypeError(\"first argument must be callable or None\")\n        super().__init__(*args, **kwargs)\n        self.default_factory = default_factory\n    def __missing__(self, key):\n        if self.default_factory is None:\n            raise KeyError(key)\n        value = self.default_factory()\n        self[key] = value\n        return value\n    def __repr__(self):\n        f = self.default_factory\n        if f is None:\n            fr = 'None'\n        elif isinstance(f, type):\n            fr = repr(f)\n        else:\n            fr = repr(f)\n        return f\"{type(self).__name__}({fr}, {dict.__repr__(self)})\"\n    def copy(self):\n        return type(self)(self.default_factory, self)\n    __copy__ = copy\n    def __reduce__(self):\n        return type(self), (self.default_factory,), None, None, iter(self.items())\n    def __or__(self, other):\n        if not isinstance(other, dict):\n            return NotImplemented\n        new = self.copy()\n        new.update(other)\n        return new\n    def __ror__(self, other):\n        if not isinstance(other, dict):\n            return NotImplemented\n        new = type(self)(self.default_factory, other)\n        new.update(self)\n        return new\ndef _count_elements(mapping, iterable):\n    mapping_get = mapping.get\n    for elem in iterable:\n        mapping[elem] = mapping_get(elem, 0) + 1\n", false);
