registerPy("importlib", () => "\"\"\"importlib (versi\u00f3n reducida).\"\"\"\nimport sys\nimport _imp_support\ndef import_module(name, package=None):\n    if name.startswith('.'):\n        if not package:\n            raise TypeError(\"the 'package' argument is required to perform a relative import for \" + repr(name))\n        level = 0\n        for character in name:\n            if character != '.':\n                break\n            level += 1\n        base = package.rsplit('.', level - 1)[0]\n        name = base + '.' + name[level:] if name[level:] else base\n    __import__(name)\n    return sys.modules[name]\ndef reload(module):\n    return _imp_support.reload(module)\ndef invalidate_caches():\n    pass\n", true);
registerPy("importlib.machinery", () => "SOURCE_SUFFIXES = ['.py']\nBYTECODE_SUFFIXES = ['.pyc']\nDEBUG_BYTECODE_SUFFIXES = ['.pyc']\nOPTIMIZED_BYTECODE_SUFFIXES = ['.pyc']\nEXTENSION_SUFFIXES = []\ndef all_suffixes():\n    return SOURCE_SUFFIXES + BYTECODE_SUFFIXES + EXTENSION_SUFFIXES\nclass ModuleSpec:\n    def __init__(self, name, loader, *, origin=None, is_package=None):\n        self.name = name\n        self.loader = loader\n        self.origin = origin\n        self.submodule_search_locations = [] if is_package else None\n        self.parent = name.rpartition('.')[0]\n        self.cached = None\n        self.has_location = origin is not None\n", false);
registerPy("importlib.util", () => "import sys\nfrom importlib.machinery import ModuleSpec\ndef find_spec(name, package=None):\n    if name in sys.modules:\n        m = sys.modules[name]\n        return getattr(m, '__spec__', None) or ModuleSpec(name, None, origin=getattr(m, '__file__', None))\n    try:\n        __import__(name)\n    except ImportError:\n        return None\n    m = sys.modules[name]\n    return ModuleSpec(name, None, origin=getattr(m, '__file__', None))\ndef spec_from_file_location(name, location=None, *, loader=None, submodule_search_locations=None):\n    return ModuleSpec(name, loader, origin=location)\ndef module_from_spec(spec):\n    import types\n    m = types.ModuleType(spec.name)\n    m.__spec__ = spec\n    return m\n", false);
