registerPy("concurrent.futures.thread", () => "\"\"\"ThreadPoolExecutor del simulador: sin hilos reales, cada llamada se ejecuta al enviarla (submit).\"\"\"\nfrom concurrent.futures import _base\n__all__ = ['ThreadPoolExecutor']\nclass BrokenThreadPool(_base.BrokenExecutor):\n    pass\nclass ThreadPoolExecutor(_base.Executor):\n    def __init__(self, max_workers=None, thread_name_prefix='', initializer=None, initargs=()):\n        if max_workers is None:\n            max_workers = 8\n        if max_workers <= 0:\n            raise ValueError(\"max_workers must be greater than 0\")\n        if initializer is not None and not callable(initializer):\n            raise TypeError(\"initializer must be a callable\")\n        self._max_workers = max_workers\n        self._thread_name_prefix = thread_name_prefix or (\"ThreadPoolExecutor-%d\" % 0)\n        self._initializer = initializer\n        self._initargs = initargs\n        self._shutdown = False\n        self._initialized = False\n    def submit(self, fn, /, *args, **kwargs):\n        if self._shutdown:\n            raise RuntimeError('cannot schedule new futures after shutdown')\n        f = _base.Future()\n        if not self._initialized:\n            self._initialized = True\n            if self._initializer is not None:\n                try:\n                    self._initializer(*self._initargs)\n                except BaseException:\n                    f.set_exception(BrokenThreadPool('A thread initializer failed, the thread pool is not usable anymore'))\n                    return f\n        if not f.set_running_or_notify_cancel():\n            return f\n        try:\n            result = fn(*args, **kwargs)\n        except BaseException as exc:\n            f.set_exception(exc)\n            self = None\n        else:\n            f.set_result(result)\n        return f\n    def shutdown(self, wait=True, *, cancel_futures=False):\n        self._shutdown = True\n", false);
